-- WOWF omits these levels. Supplement only the two explicit fishing claims
-- in the Forever fishing guide; do not reinterpret other omitted values.
local fishing=K.modules.professions.rankCatalog.professions[356].ranks
for index,level in pairs({[2]=10,[3]=20}) do
  fishing[index].level=level;fishing[index].levelStatus="VERIFIED"
  fishing[index].levelSource="https://www.method.gg/wow-forever/fishing-in-wow-forever-leveling-guide-fishing-items-trainers"
  fishing[index].levelChecked="2026-11-19"
end

-- Shared expansion requirements supplied by the user for this Forever server.
-- Keep prior per-field source facts for diagnostics; apply this common policy
-- only to the documented 150/225/300 expansions, never unsupported tiers.
local expansionLevels={[150]=10,[225]=20,[300]=35}
K.modules.professions.rankCatalog.expansionLevels=expansionLevels
for _,profession in pairs(K.modules.professions.rankCatalog.professions) do
  for _,rank in ipairs(profession.ranks) do
    local required=expansionLevels[rank.maximum]
    if required then
      rank.levelReference={level=rank.level,status=rank.levelStatus,source=rank.levelSource or rank.source}
      rank.level=required;rank.levelStatus="VERIFIED"
      rank.levelSource="사용자 제공 공통 전문기술 확장 요구 레벨"
      rank.levelSourceType="USER_CONFIRMED";rank.levelChecked="2026-11-19"
    end
  end
end
